package model;
public class User implements java.io.Serializable {
    private static final long serialVersionUID = 1L;
 private int userId,age,dailyStepGoal; private String name,email,password,gender,activityLevel,fitnessGoal,foodPreference,workoutPreference,allergies,units; private double height,weight,targetWeight,sleepGoalHours;
 public User(){}
 public User(String name,String email,String password,int age,String gender,double height,double weight,String activity,String goal,String food){this(name,email,password,age,gender,height,weight,weight,activity,goal,food,"Full Body","None","Metric",8000,8);}
 public User(String n,String e,String p,int a,String g,double h,double w,double tw,String al,String fg,String fp,String wp,String allergy,String un,int steps,double sleep){name=n;email=e;password=p;age=a;gender=g;height=h;weight=w;targetWeight=tw;activityLevel=al;fitnessGoal=fg;foodPreference=fp;workoutPreference=wp;allergies=allergy;units=un;dailyStepGoal=steps;sleepGoalHours=sleep;}
 public int getUserId(){return userId;} public void setUserId(int v){userId=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPassword(){return password;} public void setPassword(String v){password=v;} public int getAge(){return age;} public void setAge(int v){age=v;} public String getGender(){return gender;} public void setGender(String v){gender=v;} public double getHeight(){return height;} public void setHeight(double v){height=v;} public double getWeight(){return weight;} public void setWeight(double v){weight=v;} public double getTargetWeight(){return targetWeight;} public void setTargetWeight(double v){targetWeight=v;} public String getActivityLevel(){return activityLevel;} public void setActivityLevel(String v){activityLevel=v;} public String getFitnessGoal(){return fitnessGoal;} public void setFitnessGoal(String v){fitnessGoal=v;} public String getFoodPreference(){return foodPreference;} public void setFoodPreference(String v){foodPreference=v;} public String getWorkoutPreference(){return workoutPreference;} public void setWorkoutPreference(String v){workoutPreference=v;} public String getAllergies(){return allergies;} public void setAllergies(String v){allergies=v;} public String getUnits(){return units;} public void setUnits(String v){units=v;} public int getDailyStepGoal(){return dailyStepGoal;} public void setDailyStepGoal(int v){dailyStepGoal=v;} public double getSleepGoalHours(){return sleepGoalHours;} public void setSleepGoalHours(double v){sleepGoalHours=v;}
 public String toString(){return name+" ("+email+")";}
}
